import {
  Mesh,
  PlaneGeometry,
  Group,
  Vector3,
  Euler,
} from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { timeline } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

export default function createNode(config, ctx) {
  // Root container
  const root = new Group();

  // -----------------------------------------------------------------
  // Plane with texture
  // -----------------------------------------------------------------
  const texture = ctx.textureLoader.load(config.assets?.imageUrl);
  const material = new MeshBasicNodeMaterial();
  material.map = texture;
  // Ensure material uses correct alpha handling if needed
  material.transparent = true;

  const planeGeom = new PlaneGeometry(1, 1);
  const plane = new Mesh(planeGeom, material);
  root.add(plane);

  // Apply scene placement
  const pos = config.position ?? { x: 0, y: 0, z: 0 };
  const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.scale ?? { x: 1, y: 1, z: 1 };
  plane.position.set(pos.x, pos.y, pos.z);
  plane.rotation.set(rot.x, rot.y, rot.z);
  plane.scale.set(scl.x, scl.y, scl.z);

  // -----------------------------------------------------------------
  // Text label using MSDF font atlas
  // -----------------------------------------------------------------
  const txt = config.textContent ?? 'Collection 3';
  // Assume textUtils provides a helper to create a mesh from the atlas
  // The API is speculative; adjust to the actual utilities in your project.
  const textMesh = textUtils.createTextMesh(txt, {
    atlas: ctx.fontAtlas,
    atlasRegion: config.atlasRegion ?? { atlas: 0, x: 0, y: 0, w: 512, h: 320 },
    color: config.colors?.ink ?? '#16161d',
    // Typography scaling based on provided type scale (headline ~0.34 scene units)
    size: 0.34,
    // Align centre
    horizontalAlign: 'center',
    verticalAlign: 'middle',
  });

  // Position text slightly in front of the plane to avoid z‑fighting
  textMesh.position.set(0, 0, 0.001);
  root.add(textMesh);

  // -----------------------------------------------------------------
  // Cinematic primitives (none for this node, but kept for extensibility)
  // -----------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // -----------------------------------------------------------------
  // User data: handlers & cleanup
  // -----------------------------------------------------------------
  root.userData.handlers = {};

  const timelines = [];

  root.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeom.dispose();
    material.map?.dispose();
    material.dispose();

    // Dispose text resources if any
    if (textMesh) {
      textMesh.geometry?.dispose?.();
      textMesh.material?.dispose?.();
    }

    // Kill any GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
  };

  return root;
}
